def test_u78_degradation_swallowed_exceptions():
    from echo_sync import degradation
    degradation._PROBES.clear()

    @degradation.register
    def failing_probe():
        raise RuntimeError("boom")

    lines = degradation.degradation_lines()
    assert any("недоступно" in line.lower() or "failing_probe" in line.lower() or "runtimeerror" in line.lower() for line in lines)
